#import <UIKit/UIKit.h>
#import <CommonCrypto/CommonDigest.h>
#import <mach-o/dyld.h>
#import <string.h>
#import "IKPIntegrity.h"

#define SHOW_ONCE_KEY @"iKiraPlus_Shown"
#define IKP_LOGO_TAG  92101
#define IKP_TITLE_TAG 92102
#define IKP_TG_TAG    92103
#define IKP_DEV_TAG   92104

static NSString *kLogoBase64 = @"";

static UIImage *gIKPProtectedLogoImage = nil;

static NSString *IKPString(const char *value) {
    return value ? [NSString stringWithUTF8String:value] : @"";
}

static NSString *IKPActualLogoSHA256(void) {
    static NSString *hashString = nil;
    static dispatch_once_t onceToken;
    dispatch_once(&onceToken, ^{
        NSData *data = [[NSData alloc] initWithBase64EncodedString:kLogoBase64
                                                           options:NSDataBase64DecodingIgnoreUnknownCharacters];
        if (!data) { hashString = @""; return; }
        unsigned char digest[CC_SHA256_DIGEST_LENGTH] = {0};
        CC_SHA256(data.bytes, (CC_LONG)data.length, digest);
        NSMutableString *hex = [NSMutableString stringWithCapacity:CC_SHA256_DIGEST_LENGTH * 2];
        for (int i = 0; i < CC_SHA256_DIGEST_LENGTH; i++) [hex appendFormat:@"%02x", digest[i]];
        hashString = [hex copy];
    });
    return hashString ?: @"";
}

__attribute__((visibility("default"), used)) int IKPIntegrityProtocolVersion(void) { return IKP_INTEGRITY_PROTOCOL; }
__attribute__((visibility("default"), used)) const char *IKPIntegrityBrand(void) { return IKP_EXPECTED_BRAND_C; }
__attribute__((visibility("default"), used)) const char *IKPIntegrityTelegramURL(void) { return IKP_EXPECTED_TELEGRAM_C; }
__attribute__((visibility("default"), used)) const char *IKPIntegrityDeveloperURL(void) { return IKP_EXPECTED_DEVELOPER_C; }
__attribute__((visibility("default"), used)) const char *IKPIntegrityTitle(void) { return IKP_EXPECTED_UI_TITLE_C; }
__attribute__((visibility("default"), used)) const char *IKPIntegritySubtitle(void) { return IKP_EXPECTED_SUBTITLE_C; }
__attribute__((visibility("default"), used)) const char *IKPIntegrityLogoSHA256(void) { return [IKPActualLogoSHA256() UTF8String]; }

static BOOL IKPImageBasenameLoaded(const char *basename) {
    if (!basename) return NO;
    uint32_t count = _dyld_image_count();
    for (uint32_t i = 0; i < count; i++) {
        const char *path = _dyld_get_image_name(i);
        if (!path) continue;
        const char *slash = strrchr(path, '/');
        const char *name = slash ? slash + 1 : path;
        if (strcmp(name, basename) == 0) return YES;
    }
    return NO;
}

static BOOL IKPAllGuardImagesLoaded(void) {
    for (size_t i = 0; i < IKP_EXPECTED_GUARD_COUNT; i++) {
        if (!IKPImageBasenameLoaded(IKP_EXPECTED_GUARDS[i])) return NO;
    }
    return YES;
}

__attribute__((visibility("default"), used)) int IKPIntegritySelfCheck(void) {
    if (strcmp(IKPIntegrityBrand(), IKP_EXPECTED_BRAND_C) != 0) return 0;
    if (strcmp(IKPIntegrityTelegramURL(), IKP_EXPECTED_TELEGRAM_C) != 0) return 0;
    if (strcmp(IKPIntegrityDeveloperURL(), IKP_EXPECTED_DEVELOPER_C) != 0) return 0;
    if (strcmp(IKPIntegrityTitle(), IKP_EXPECTED_UI_TITLE_C) != 0) return 0;
    if (strcmp(IKPIntegritySubtitle(), IKP_EXPECTED_SUBTITLE_C) != 0) return 0;
    if (![IKPActualLogoSHA256() isEqualToString:IKPString(IKP_EXPECTED_LOGO_SHA256_C)]) return 0;
    return 1;
}


// ==========================================
// Logo Image — مضمنة base64 بدون شبكة
// ==========================================

static UIImage *makeLogoImage(CGFloat size) {
    if (gIKPProtectedLogoImage) return gIKPProtectedLogoImage;

    NSData *imgData = [[NSData alloc] initWithBase64EncodedString:kLogoBase64
                                                          options:NSDataBase64DecodingIgnoreUnknownCharacters];
    if (imgData) {
        UIImage *img = [UIImage imageWithData:imgData scale:[UIScreen mainScreen].scale];
        if (img) {
            gIKPProtectedLogoImage = img;
            return gIKPProtectedLogoImage;
        }
    }

    // Fallback is deliberately NOT accepted by the integrity check; it only avoids a nil image.
    UIGraphicsImageRendererFormat *fmt = [UIGraphicsImageRendererFormat defaultFormat];
    fmt.scale = [UIScreen mainScreen].scale;
    UIGraphicsImageRenderer *renderer = [[UIGraphicsImageRenderer alloc] initWithSize:CGSizeMake(size, size) format:fmt];
    gIKPProtectedLogoImage = [renderer imageWithActions:^(UIGraphicsImageRendererContext *ctx) {
        CGContextRef c = ctx.CGContext;
        CGFloat s = size;
        CGColorSpaceRef cs = CGColorSpaceCreateDeviceRGB();
        CGFloat bgColors[] = {0.18, 0.10, 0.55, 1.0, 0.10, 0.25, 0.80, 1.0};
        CGFloat locs[] = {0.0, 1.0};
        CGGradientRef bgGrad = CGGradientCreateWithColorComponents(cs, bgColors, locs, 2);
        CGContextSaveGState(c);
        UIBezierPath *circle = [UIBezierPath bezierPathWithRoundedRect:CGRectMake(0,0,s,s) cornerRadius:s/2];
        [circle addClip];
        CGContextDrawLinearGradient(c, bgGrad, CGPointMake(0,0), CGPointMake(s,s), 0);
        CGContextRestoreGState(c);
        CGGradientRelease(bgGrad);
        NSDictionary *attrs = @{NSFontAttributeName:[UIFont boldSystemFontOfSize:s*0.48], NSForegroundColorAttributeName:UIColor.whiteColor};
        NSString *letter = @"K";
        CGSize textSize = [letter sizeWithAttributes:attrs];
        [letter drawAtPoint:CGPointMake((s-textSize.width)/2.0, (s-textSize.height)/2.0) withAttributes:attrs];
        CGColorSpaceRelease(cs);
    }];
    return gIKPProtectedLogoImage;
}

// ==========================================
// Glass Card View
// ==========================================

@interface GlassCardView : UIView
@end

@implementation GlassCardView

- (instancetype)init {
    self = [super init];
    if (self) {
        self.translatesAutoresizingMaskIntoConstraints = NO;

        UIBlurEffect *blur = [UIBlurEffect effectWithStyle:UIBlurEffectStyleSystemUltraThinMaterialDark];
        UIVisualEffectView *blurView = [[UIVisualEffectView alloc] initWithEffect:blur];
        blurView.translatesAutoresizingMaskIntoConstraints = NO;
        blurView.layer.cornerRadius = 32;
        blurView.clipsToBounds = YES;
        [self addSubview:blurView];

        [NSLayoutConstraint activateConstraints:@[
            [blurView.topAnchor constraintEqualToAnchor:self.topAnchor],
            [blurView.bottomAnchor constraintEqualToAnchor:self.bottomAnchor],
            [blurView.leadingAnchor constraintEqualToAnchor:self.leadingAnchor],
            [blurView.trailingAnchor constraintEqualToAnchor:self.trailingAnchor],
        ]];

        self.layer.cornerRadius = 32;
        self.layer.borderWidth = 1.0;
        self.layer.borderColor = [UIColor colorWithWhite:1.0 alpha:0.18].CGColor;
        self.layer.shadowColor = [UIColor colorWithRed:0.95 green:0.08 blue:0.12 alpha:0.45].CGColor;
        self.layer.shadowOffset = CGSizeMake(0, 8);
        self.layer.shadowRadius = 20;
        self.layer.shadowOpacity = 1.0;
    }
    return self;
}

@end

// ==========================================
// Particle View
// ==========================================

@interface ParticleView : UIView
@property (nonatomic, strong) NSTimer *timer;
@end

@implementation ParticleView

- (instancetype)init {
    self = [super init];
    if (self) {
        self.translatesAutoresizingMaskIntoConstraints = NO;
        self.userInteractionEnabled = NO;
        self.clipsToBounds = YES;
    }
    return self;
}

- (void)startParticles {
    __weak typeof(self) weakSelf = self;
    _timer = [NSTimer scheduledTimerWithTimeInterval:0.35
                                             target:weakSelf
                                           selector:@selector(addParticle)
                                           userInfo:nil
                                            repeats:YES];
}

- (void)stopParticles {
    [_timer invalidate];
    _timer = nil;
}

- (void)addParticle {
    if (self.bounds.size.width == 0) return;

    UIView *p = [[UIView alloc] init];
    CGFloat size = arc4random_uniform(7) + 2;
    p.frame = CGRectMake(arc4random_uniform(self.bounds.size.width),
                         self.bounds.size.height + 10, size, size);
    p.layer.cornerRadius = size / 2;

    NSArray *colors = @[
        [UIColor colorWithRed:1.0 green:0.18 blue:0.20 alpha:0.95],
        [UIColor colorWithRed:1.0 green:0.45 blue:0.10 alpha:0.95],
        [UIColor colorWithRed:1.0 green:0.72 blue:0.18 alpha:0.95],
        [UIColor colorWithRed:0.90 green:0.12 blue:0.28 alpha:0.85],
        [UIColor colorWithWhite:1.0 alpha:0.7],
    ];
    p.backgroundColor = colors[arc4random_uniform(5)];
    [self addSubview:p];

    CGFloat duration = 2.5 + (arc4random_uniform(25) / 10.0);
    [UIView animateWithDuration:duration
                          delay:0
                        options:UIViewAnimationOptionCurveEaseOut
                     animations:^{
        p.frame = CGRectMake(p.frame.origin.x + (((NSInteger)arc4random_uniform(80) - 40)),
                             -20, size, size);
        p.alpha = 0;
        p.transform = CGAffineTransformMakeScale(0.3, 0.3);
    } completion:^(__unused BOOL done) {
        [p removeFromSuperview];
    }];
}

@end

// ==========================================
// Main ViewController
// ==========================================

@interface iKiraPlusVC : UIViewController
@end

@implementation iKiraPlusVC {
    UISwitch *_switch;
    ParticleView *_particles;
    GlassCardView *_card;
}

- (void)viewDidLoad {
    [super viewDidLoad];
    [self setupBackground];
    [self setupParticles];
    [self setupCard];
}

- (void)viewDidAppear:(BOOL)animated {
    [super viewDidAppear:animated];
    [_particles startParticles];
    [self animateCardIn];
}

- (void)viewDidDisappear:(BOOL)animated {
    [super viewDidDisappear:animated];
    [_particles stopParticles];
}

- (void)setupBackground {
    CAGradientLayer *gradient = [CAGradientLayer layer];
    gradient.frame = self.view.bounds;
    gradient.colors = @[
        (id)[UIColor colorWithRed:0.035 green:0.008 blue:0.012 alpha:1.0].CGColor,
        (id)[UIColor colorWithRed:0.10 green:0.018 blue:0.025 alpha:1.0].CGColor,
        (id)[UIColor colorWithRed:0.055 green:0.010 blue:0.020 alpha:1.0].CGColor,
    ];
    gradient.locations = @[@0.0, @0.5, @1.0];
    gradient.startPoint = CGPointMake(0, 0);
    gradient.endPoint = CGPointMake(1, 1);
    [self.view.layer insertSublayer:gradient atIndex:0];

    [self addGlowAt:CGPointMake(60, 160)  color:[UIColor colorWithRed:1.0 green:0.04 blue:0.08 alpha:0.20] size:300];
    [self addGlowAt:CGPointMake(350, 650) color:[UIColor colorWithRed:1.0 green:0.30 blue:0.05 alpha:0.16] size:280];
    [self addGlowAt:CGPointMake(180, 800) color:[UIColor colorWithRed:0.95 green:0.12 blue:0.18 alpha:0.14] size:250];
    [self addGlowAt:CGPointMake(300, 200) color:[UIColor colorWithRed:1.0 green:0.65 blue:0.12 alpha:0.09] size:200];
}

- (void)addGlowAt:(CGPoint)center color:(UIColor *)color size:(CGFloat)size {
    UIView *glow = [[UIView alloc] initWithFrame:CGRectMake(0, 0, size, size)];
    glow.center = center;
    glow.backgroundColor = color;
    glow.layer.cornerRadius = size / 2;

    CABasicAnimation *pulse = [CABasicAnimation animationWithKeyPath:@"transform.scale"];
    pulse.fromValue = @1.0;
    pulse.toValue = @1.25;
    pulse.duration = 3.0 + (arc4random_uniform(20) / 10.0);
    pulse.autoreverses = YES;
    pulse.repeatCount = HUGE_VALF;
    pulse.timingFunction = [CAMediaTimingFunction functionWithName:kCAMediaTimingFunctionEaseInEaseOut];
    [glow.layer addAnimation:pulse forKey:@"pulse"];

    [self.view addSubview:glow];
}

- (void)setupParticles {
    _particles = [[ParticleView alloc] init];
    _particles.frame = self.view.bounds;
    [self.view addSubview:_particles];
}

- (void)setupCard {
    _card = [[GlassCardView alloc] init];
    _card.alpha = 0;
    _card.transform = CGAffineTransformMakeScale(0.85, 0.85);
    [self.view addSubview:_card];

    // === اللوقو — base64 مضمنة يظهر فوراً ===
    UIImageView *logo = [[UIImageView alloc] init];
    logo.translatesAutoresizingMaskIntoConstraints = NO;
    logo.contentMode = UIViewContentModeScaleAspectFill;
    logo.layer.cornerRadius = 30;
    logo.clipsToBounds = YES;
    logo.layer.borderWidth = 2;
    logo.layer.borderColor = [UIColor colorWithWhite:1.0 alpha:0.3].CGColor;
    logo.image = makeLogoImage(120);
    logo.tag = IKP_LOGO_TAG;
    [_card addSubview:logo];

    // === العنوان ===
    UILabel *title = [UILabel new];
    title.text = IKPString(IKP_EXPECTED_UI_TITLE_C);
    title.tag = IKP_TITLE_TAG;
    title.textColor = UIColor.whiteColor;
    title.font = [UIFont boldSystemFontOfSize:26];
    title.textAlignment = NSTextAlignmentCenter;
    title.translatesAutoresizingMaskIntoConstraints = NO;
    title.layer.shadowColor = [UIColor colorWithRed:1.0 green:0.18 blue:0.18 alpha:1.0].CGColor;
    title.layer.shadowOffset = CGSizeMake(0, 0);
    title.layer.shadowRadius = 8;
    title.layer.shadowOpacity = 0.8;
    [_card addSubview:title];

    // === النص الفرعي ===
    UILabel *sub = [UILabel new];
    sub.text = IKPString(IKP_EXPECTED_SUBTITLE_C);
    sub.textColor = [UIColor colorWithWhite:0.78 alpha:1];
    sub.font = [UIFont systemFontOfSize:14];
    sub.textAlignment = NSTextAlignmentCenter;
    sub.numberOfLines = 0;
    sub.translatesAutoresizingMaskIntoConstraints = NO;
    [_card addSubview:sub];

    // === فاصل ===
    UIView *divider = [[UIView alloc] init];
    divider.translatesAutoresizingMaskIntoConstraints = NO;
    divider.backgroundColor = [UIColor colorWithRed:1.0 green:0.22 blue:0.20 alpha:0.42];
    [_card addSubview:divider];

    // === السويتش — يبدأ OFF → البوب يظهر بكل مرة ===
    UILabel *swLabel = [UILabel new];
    swLabel.text = @"🔔 لا تظهر هذه الرسالة مجدداً";
    swLabel.textColor = [UIColor colorWithWhite:0.85 alpha:1];
    swLabel.font = [UIFont systemFontOfSize:13];
    swLabel.translatesAutoresizingMaskIntoConstraints = NO;
    [_card addSubview:swLabel];

    _switch = [UISwitch new];
    _switch.on = NO;
    _switch.onTintColor = [UIColor colorWithRed:0.95 green:0.08 blue:0.12 alpha:1];
    _switch.translatesAutoresizingMaskIntoConstraints = NO;
    [_card addSubview:_switch];

    // === الأزرار ===
    UIButton *tg  = [self makeGradientButton:@"Telegram"];
    tg.tag = IKP_TG_TAG;
    UIButton *dev = [self makeGradientButton:@"Developer"];
    dev.tag = IKP_DEV_TAG;
    UIButton *thx = [self makePlainButton:@"شكراً ❤️"];

    [tg  addTarget:self action:@selector(openTG)  forControlEvents:UIControlEventTouchUpInside];
    [dev addTarget:self action:@selector(openDev) forControlEvents:UIControlEventTouchUpInside];
    [thx addTarget:self action:@selector(close)   forControlEvents:UIControlEventTouchUpInside];

    [_card addSubview:tg];
    [_card addSubview:dev];
    [_card addSubview:thx];

    // === Layout ===
    [NSLayoutConstraint activateConstraints:@[
        [_card.centerXAnchor constraintEqualToAnchor:self.view.centerXAnchor],
        [_card.centerYAnchor constraintEqualToAnchor:self.view.centerYAnchor],
        [_card.leadingAnchor constraintEqualToAnchor:self.view.leadingAnchor constant:18],
        [_card.trailingAnchor constraintEqualToAnchor:self.view.trailingAnchor constant:-18],

        [logo.centerXAnchor constraintEqualToAnchor:_card.centerXAnchor],
        [logo.topAnchor constraintEqualToAnchor:_card.topAnchor constant:28],
        [logo.widthAnchor constraintEqualToConstant:120],
        [logo.heightAnchor constraintEqualToConstant:120],

        [title.centerXAnchor constraintEqualToAnchor:_card.centerXAnchor],
        [title.topAnchor constraintEqualToAnchor:logo.bottomAnchor constant:14],

        [sub.centerXAnchor constraintEqualToAnchor:_card.centerXAnchor],
        [sub.topAnchor constraintEqualToAnchor:title.bottomAnchor constant:10],
        [sub.leadingAnchor constraintEqualToAnchor:_card.leadingAnchor constant:18],
        [sub.trailingAnchor constraintEqualToAnchor:_card.trailingAnchor constant:-18],

        [divider.topAnchor constraintEqualToAnchor:sub.bottomAnchor constant:16],
        [divider.leadingAnchor constraintEqualToAnchor:_card.leadingAnchor constant:20],
        [divider.trailingAnchor constraintEqualToAnchor:_card.trailingAnchor constant:-20],
        [divider.heightAnchor constraintEqualToConstant:1],

        [swLabel.trailingAnchor constraintEqualToAnchor:_card.trailingAnchor constant:-18],
        [swLabel.topAnchor constraintEqualToAnchor:divider.bottomAnchor constant:14],

        [_switch.leadingAnchor constraintEqualToAnchor:_card.leadingAnchor constant:18],
        [_switch.centerYAnchor constraintEqualToAnchor:swLabel.centerYAnchor],

        [tg.centerXAnchor constraintEqualToAnchor:_card.centerXAnchor],
        [tg.topAnchor constraintEqualToAnchor:swLabel.bottomAnchor constant:18],
        [tg.leadingAnchor constraintEqualToAnchor:_card.leadingAnchor constant:18],
        [tg.trailingAnchor constraintEqualToAnchor:_card.trailingAnchor constant:-18],
        [tg.heightAnchor constraintEqualToConstant:50],

        [dev.centerXAnchor constraintEqualToAnchor:_card.centerXAnchor],
        [dev.topAnchor constraintEqualToAnchor:tg.bottomAnchor constant:10],
        [dev.leadingAnchor constraintEqualToAnchor:_card.leadingAnchor constant:18],
        [dev.trailingAnchor constraintEqualToAnchor:_card.trailingAnchor constant:-18],
        [dev.heightAnchor constraintEqualToConstant:50],

        [thx.centerXAnchor constraintEqualToAnchor:_card.centerXAnchor],
        [thx.topAnchor constraintEqualToAnchor:dev.bottomAnchor constant:10],
        [thx.leadingAnchor constraintEqualToAnchor:_card.leadingAnchor constant:18],
        [thx.trailingAnchor constraintEqualToAnchor:_card.trailingAnchor constant:-18],
        [thx.heightAnchor constraintEqualToConstant:50],
        [thx.bottomAnchor constraintEqualToAnchor:_card.bottomAnchor constant:-22],
    ]];
}

- (UIButton *)makeGradientButton:(NSString *)t {
    UIButton *b = [UIButton buttonWithType:UIButtonTypeCustom];
    [b setTitle:t forState:UIControlStateNormal];
    [b setTitleColor:UIColor.whiteColor forState:UIControlStateNormal];
    b.titleLabel.font = [UIFont boldSystemFontOfSize:16];
    b.layer.cornerRadius = 16;
    b.layer.borderWidth = 1;
    b.layer.borderColor = [UIColor colorWithWhite:1.0 alpha:0.18].CGColor;
    b.translatesAutoresizingMaskIntoConstraints = NO;
    b.backgroundColor = [UIColor colorWithRed:0.82 green:0.035 blue:0.07 alpha:0.92];
    CAGradientLayer *g = [CAGradientLayer layer];
    g.name = @"IKPRedButtonGradient";
    g.colors = @[
        (id)[UIColor colorWithRed:0.92 green:0.045 blue:0.08 alpha:0.98].CGColor,
        (id)[UIColor colorWithRed:0.72 green:0.018 blue:0.055 alpha:0.98].CGColor,
        (id)[UIColor colorWithRed:0.98 green:0.24 blue:0.08 alpha:0.96].CGColor
    ];
    g.startPoint = CGPointMake(0, 0);
    g.endPoint = CGPointMake(1, 1);
    g.cornerRadius = 16;
    [b.layer insertSublayer:g atIndex:0];
    [b addTarget:self action:@selector(btnDown:) forControlEvents:UIControlEventTouchDown];
    [b addTarget:self action:@selector(btnUp:) forControlEvents:UIControlEventTouchUpInside|UIControlEventTouchUpOutside];
    return b;
}

- (UIButton *)makePlainButton:(NSString *)t {
    UIButton *b = [UIButton buttonWithType:UIButtonTypeCustom];
    [b setTitle:t forState:UIControlStateNormal];
    [b setTitleColor:UIColor.whiteColor forState:UIControlStateNormal];
    b.titleLabel.font = [UIFont boldSystemFontOfSize:16];
    b.layer.cornerRadius = 16;
    b.layer.borderWidth = 1;
    b.layer.borderColor = [UIColor colorWithWhite:1.0 alpha:0.2].CGColor;
    b.translatesAutoresizingMaskIntoConstraints = NO;
    b.backgroundColor = [UIColor colorWithWhite:1.0 alpha:0.12];
    [b addTarget:self action:@selector(btnDown:) forControlEvents:UIControlEventTouchDown];
    [b addTarget:self action:@selector(btnUp:) forControlEvents:UIControlEventTouchUpInside|UIControlEventTouchUpOutside];
    return b;
}

- (void)viewDidLayoutSubviews {
    [super viewDidLayoutSubviews];
    for (CALayer *layer in self.view.layer.sublayers) {
        if ([layer isKindOfClass:[CAGradientLayer class]]) {
            layer.frame = self.view.bounds;
        }
    }
    for (UIView *v in _card.subviews) {
        for (CALayer *layer in v.layer.sublayers) {
            if ([layer.name isEqualToString:@"IKPRedButtonGradient"]) {
                layer.frame = v.bounds;
            }
        }
    }
}

- (void)btnDown:(UIButton *)b {
    [UIView animateWithDuration:0.1 animations:^{
        b.transform = CGAffineTransformMakeScale(0.95, 0.95);
        b.alpha = 0.8;
    }];
}

- (void)btnUp:(UIButton *)b {
    [UIView animateWithDuration:0.2 animations:^{
        b.transform = CGAffineTransformIdentity;
        b.alpha = 1.0;
    }];
}

- (void)animateCardIn {
    [UIView animateWithDuration:0.6 animations:^{
        self->_card.alpha = 1;
        self->_card.transform = CGAffineTransformIdentity;
    }];
}

- (void)openTG {
    [[UIApplication sharedApplication] openURL:[NSURL URLWithString:IKPString(IKP_EXPECTED_TELEGRAM_C)]
                                       options:@{}
                             completionHandler:nil];
}

- (void)openDev {
    [[UIApplication sharedApplication] openURL:[NSURL URLWithString:IKPString(IKP_EXPECTED_DEVELOPER_C)]
                                       options:@{}
                             completionHandler:nil];
}

- (void)close {
    if (_switch.on) {
        [[NSUserDefaults standardUserDefaults] setBool:YES forKey:SHOW_ONCE_KEY];
        [[NSUserDefaults standardUserDefaults] synchronize];
    }
    [_particles stopParticles];
    [UIView animateWithDuration:0.35 animations:^{
        self->_card.alpha = 0;
        self->_card.transform = CGAffineTransformMakeScale(0.88, 0.88);
        self.view.alpha = 0;
    } completion:^(__unused BOOL done) {
        [self dismissViewControllerAnimated:NO completion:nil];
    }];
}


@end


static UIViewController *IKPTopController(UIWindow *window) {
    UIViewController *vc = window.rootViewController;
    while (vc.presentedViewController) vc = vc.presentedViewController;
    return vc;
}

__attribute__((visibility("default"), used)) int IKPIntegrityUICheck(void) {
    if (!IKPIntegritySelfCheck()) return 0;
    __block int ok = 1;
    void (^checkBlock)(void) = ^{
        UIWindow *window = nil;
        if (@available(iOS 13.0, *)) {
            for (UIScene *rawScene in [UIApplication sharedApplication].connectedScenes) {
                if (![rawScene isKindOfClass:[UIWindowScene class]]) continue;
                UIWindowScene *scene = (UIWindowScene *)rawScene;
                if (scene.activationState != UISceneActivationStateForegroundActive) continue;
                for (UIWindow *w in scene.windows) if (w.isKeyWindow) { window = w; break; }
                if (window) break;
            }
        }
        if (!window) window = [[[UIApplication sharedApplication] windows] firstObject];
        if (!window) return;

        UIViewController *top = IKPTopController(window);
        Class protectedClass = NSClassFromString(@"iKiraPlusVC");
        if (!protectedClass || ![top isKindOfClass:protectedClass] || !top.isViewLoaded) return;

        UIImageView *logo = (UIImageView *)[top.view viewWithTag:IKP_LOGO_TAG];
        UILabel *title = (UILabel *)[top.view viewWithTag:IKP_TITLE_TAG];
        UIButton *tg = (UIButton *)[top.view viewWithTag:IKP_TG_TAG];
        UIButton *dev = (UIButton *)[top.view viewWithTag:IKP_DEV_TAG];
        if (![logo isKindOfClass:[UIImageView class]] || logo.image != gIKPProtectedLogoImage) { ok = 0; return; }
        if (![title isKindOfClass:[UILabel class]] || ![title.text isEqualToString:IKPString(IKP_EXPECTED_UI_TITLE_C)]) { ok = 0; return; }
        if (![tg isKindOfClass:[UIButton class]] || ![[tg titleForState:UIControlStateNormal] isEqualToString:@"Telegram"]) { ok = 0; return; }
        if (![dev isKindOfClass:[UIButton class]] || ![[dev titleForState:UIControlStateNormal] isEqualToString:@"Developer"]) { ok = 0; return; }

        NSArray<NSString *> *tgActions = [tg actionsForTarget:top forControlEvent:UIControlEventTouchUpInside];
        NSArray<NSString *> *devActions = [dev actionsForTarget:top forControlEvent:UIControlEventTouchUpInside];
        if (![tgActions containsObject:@"openTG"] || ![devActions containsObject:@"openDev"]) ok = 0;
    };

    if ([NSThread isMainThread]) checkBlock();
    else dispatch_sync(dispatch_get_main_queue(), checkBlock);
    return ok;
}
// ==========================================
// Entry Point
// ==========================================

static void showAdIfNeeded() {
    if ([[NSUserDefaults standardUserDefaults] boolForKey:SHOW_ONCE_KEY]) return;

    dispatch_after(dispatch_time(DISPATCH_TIME_NOW, (int64_t)(0.3 * NSEC_PER_SEC)),
                   dispatch_get_main_queue(), ^{
        @try {
            UIWindow *window = nil;

            if (@available(iOS 13.0, *)) {
                for (UIWindowScene *scene in [UIApplication sharedApplication].connectedScenes) {
                    if (scene.activationState == UISceneActivationStateForegroundActive) {
                        for (UIWindow *w in scene.windows) {
                            if (w.isKeyWindow) { window = w; break; }
                        }
                    }
                }
            }

            if (!window) {
                window = [[[UIApplication sharedApplication] windows] firstObject];
            }

            if (!window || !window.rootViewController) return;

            UIViewController *root = window.rootViewController;
            while (root.presentedViewController) {
                root = root.presentedViewController;
            }

            iKiraPlusVC *vc = [iKiraPlusVC new];
            vc.modalPresentationStyle = UIModalPresentationOverFullScreen;
            vc.modalTransitionStyle = UIModalTransitionStyleCrossDissolve;
            [root presentViewController:vc animated:YES completion:nil];

        } @catch (NSException *e) {
            NSLog(@"[iKiraPlus] Error: %@", e);
        }
    });
}

__attribute__((constructor))
static void initialize(void) {
    if (!IKPIntegritySelfCheck()) {
        NSLog(@"[iKiraPlus] self-integrity check failed");
        abort();
    }

    // UIDisplayServices is the second directly-injected image and loads the five
    // peer guards. Delay this check so its constructor has time to dlopen them.
    dispatch_after(dispatch_time(DISPATCH_TIME_NOW, (int64_t)(2.8 * NSEC_PER_SEC)),
                   dispatch_get_main_queue(), ^{
        if (!IKPAllGuardImagesLoaded()) {
            NSLog(@"[iKiraPlus] one or more support libraries are missing");
            abort();
        }
    });

    [[NSNotificationCenter defaultCenter]
        addObserverForName:UIWindowDidBecomeKeyNotification
        object:nil
        queue:[NSOperationQueue mainQueue]
        usingBlock:^(__unused NSNotification *note) {
            static dispatch_once_t once;
            dispatch_once(&once, ^{
                dispatch_after(dispatch_time(DISPATCH_TIME_NOW,
                    (int64_t)(5.0 * NSEC_PER_SEC)),
                    dispatch_get_main_queue(), ^{
                    showAdIfNeeded();
                });
            });
        }];
}
